// 取得所有輸入的項目
const allItems = items;

// 過濾邏輯
const filteredItems = allItems.filter(item => {
  const data = item.json.data;

  // 1. 先排除「附件」和「筆記」類型，我們只要主條目 (如 journalArticle)
  // 因為附件會跟著主條目一起被抓下來，我們不想重複處理
  if (data.itemType === 'attachment' || data.itemType === 'note') {
    return false;
  }

  // 2. 檢查是否有 Tags
  const tags = data.tags || [];

  // 3. 檢查是否有 "Analyzed" 標籤
  // some() 會檢查陣列中是否「至少有一個」符合條件
  const isAnalyzed = tags.some(t => t.tag === 'Analyzed');

  // 4. 如果「已經分析過 (isAnalyzed 為 true)」，我們就回傳 false (不要這個項目)
  // 反之則保留
  return !isAnalyzed;
});

return filteredItems;

// 取得這篇文章的所有子項目
const children = items.map(item => item.json);

// 找到 PDF 類型的附件
const pdfAttachment = children.find(child => 
  child.data.contentType === 'application/pdf' && 
  child.data.filename
);

if (pdfAttachment) {
  // 狀況 A: 找到 PDF -> hasPdf = true
  return [{
    json: {
      hasPdf: true, // 給下一個 If 節點判斷用
      parentKey: pdfAttachment.data.parentItem,
      attachmentKey: pdfAttachment.key,
      filename: pdfAttachment.data.filename,
      title: pdfAttachment.data.title
    }
  }];
} else {
  // 狀況 B: 沒找到 PDF -> hasPdf = false
  // 關鍵：即使沒東西，也要回傳一個 dummy 物件，讓流程能繼續往下走
  return [{
    json: {
      hasPdf: false,
      title: "No PDF Found"
    }
  }];
}

// 取得 Binary 資料的 Key (通常是 data 或 file_xxx)
const binaryKeys = Object.keys(items[0].binary);
const pdfKey = binaryKeys[0];

// ★ 關鍵修正：強制讀取檔案 Buffer 並轉為 Base64 字串
// 參數 0 代表「目前這批資料的第 0 筆」(因為我們有 SplitInBatches，所以永遠是 0)
const buffer = await this.helpers.getBinaryDataBuffer(0, pdfKey);
const pdfBase64 = buffer.toString('base64');

// 準備 Prompt (提示詞)
const promptText = `你是一位專業的研究助理。請分析附件文獻，直接產出筆記內容。

**筆記結構要求：**
1. 每個段落標題請務必使用 **第一層標題 (#)** (例如：# 實驗目的)。
2. **絕對不要** 輸出 YAML Frontmatter (--- ... ---)。
3. **絕對不要** 使用 Markdown 代碼區塊 (不要包在 \`\`\`markdown ... \`\`\` 裡面)。
4. 請跳過所有開場白，直接開始寫內容。

**內容大綱：**
# 實驗目的
(簡述研究問題或假設)

# 實驗方法
(說明設計、參與者、工具)

# 實驗結果
(關鍵發現與數據)

# 重要概念與貢獻
(核心理論或實質貢獻)`;

// 建構 Request Body
const requestBody = {
  contents: [
    {
      parts: [
        {
          text: promptText
        },
        {
          inline_data: {
            mime_type: "application/pdf",
            data: pdfBase64 // 這裡現在是真正的 Base64 編碼了
          }
        }
      ]
    }
  ]
};

// 輸出
return [
  {
    json: {
      requestBody: requestBody,
      fileName: items[0].binary[pdfKey].fileName
    }
  }
];

// 1. 取得 Gemini 產生的 Markdown 內容
const candidate = items[0].json.candidates?.[0];
let mdContent = candidate?.content?.parts?.[0]?.text || "";

// 2. 清洗 Gemini 的輸出 (移除可能殘留的 code block 或 yaml)
// 移除開頭的 ```markdown 或 ```
mdContent = mdContent.replace(/^```[a-z]*\n/i, "");
// 移除結尾的 ```
mdContent = mdContent.replace(/```$/i, "");
// 如果 AI 還是不聽話寫了 --- 開頭，把它去掉
mdContent = mdContent.replace(/^---\n[\s\S]*?\n---\n/, "");
// 移除前後多餘空白
mdContent = mdContent.trim();


// 3. 抓取 Zotero 原始資料 (從 Split In Batches 節點)
const zoteroData = $node["Split In Batches"].json.data;

// --- [開始] 準備 YAML 資料 ---

// [A] 作者處理 (將 array 轉為字串: "Smith, J., Doe, A.")
let authors = "Unknown";
if (zoteroData.creators && zoteroData.creators.length > 0) {
  authors = zoteroData.creators
    .map(c => `${c.lastName}${c.firstName ? ', ' + c.firstName : ''}`)
    .join("; "); // Obsidian tags 用分號隔開比較安全，或用逗號
}

// [B] 來源網址
const sourceUrl = zoteroData.url || "";

// [C] 年份
let year = "";
if (zoteroData.date) {
  const yearMatch = zoteroData.date.toString().match(/\d{4}/);
  if (yearMatch) year = yearMatch[0];
}

// [D] 期刊
const journal = zoteroData.publicationTitle || "";

// [E] 組裝 YAML Frontmatter
const yamlFrontmatter = `---
tags:
  - Analyzed
  - Literature
author: "${authors}"
year: ${year}
journal: "${journal}"
source: "${sourceUrl}"
created: ${new Date().toISOString().split('T')[0]}
---

`; // 注意這裡保留一個換行

// --- [結束] YAML 資料 ---


// 4. 準備檔名 (沿用您之前的邏輯)
let metaParts = [];
if (journal) metaParts.push(journal.trim());
if (year) metaParts.push(year);
if (zoteroData.volume) metaParts.push("V" + zoteroData.volume.trim());
if (zoteroData.pages) metaParts.push("pp" + zoteroData.pages.trim());

const metaString = metaParts.join(" ");
const title = (zoteroData.title || "Untitled").trim();
let finalName = metaString ? `${metaString}_${title}` : title;
finalName = finalName.replace(/[\\/:*?"<>|]/g, "") + ".md";


// 5. 組合最終內容：YAML + Gemini 筆記
const finalContent = yamlFrontmatter + mdContent;


// 6. 輸出資料
const binaryData = Buffer.from(finalContent, 'utf8');

return [{
  json: {
    fileName: finalName,
    uploadPath: "1_RehabVisionResearch/Atlas Literature/" + finalName
  },
  binary: {
    data: {
      data: binaryData.toString('base64'),
      mimeType: 'text/markdown',
      fileName: finalName
    }
  }
}];

// 1. 從 Loop 節點抓取最原始的 Zotero 資料
const zoteroItem = $node["Split In Batches"].json;

// 2. 取得目前的標籤陣列
const currentTags = zoteroItem.data.tags || [];

// 3. 檢查並新增 "Analyzed" 標籤
const hasTag = currentTags.some(t => t.tag === 'Analyzed');
let newTags = currentTags;

if (!hasTag) {
  newTags = [...currentTags, { tag: 'Analyzed' }];
}

// 4. ★ 關鍵修正：輸出時包含 version 號碼
return [{
  json: {
    itemKey: zoteroItem.key,
    tags: newTags,
    version: zoteroItem.version // 或是 zoteroItem.data.version，Zotero 兩處通常都有，這裡抓最外層的
  }
}];
